import itertools

def solve_small_m(m_max):
    for m in range(2, m_max + 1):
        possible = True
        for res in itertools.combinations_with_replacement(range(m), m):
            if sum(res) % m == 0:
                continue

            distinct_res = sorted(list(set(res)))
            num_distinct = len(distinct_res)
            initial_counts = tuple(res.count(r) for r in distinct_res)

            dp_table = [{} for _ in range(m + 1)]
            dp_table[0][0] = {tuple([0] * num_distinct)}
            for i in range(1, m + 1):
                for s in dp_table[i-1]:
                    for r_idx in range(num_distinct):
                        for current_counts in dp_table[i-1][s]:
                            if current_counts[r_idx] < initial_counts[r_idx]:
                                new_counts = list(current_counts)
                                new_counts[r_idx] += 1
                                new_s = (s + i * distinct_res[r_idx]) % m
                                if new_s not in dp_table[i]:
                                    dp_table[i][new_s] = set()
                                dp_table[i][new_s].add(tuple(new_counts))

            if not dp_table[m][0]:
                possible = False
                break

        print(f"m={m}: {possible}")
        if not possible:
            # If we find an m that's not possible, it means the condition 
            # is not satisfied for that m. 
            pass

