def count_prime_powers(n):
    count = 0
    for m in range(2, n + 1):
        # Check if m is a prime power p^k for some k >= 1
        is_prime_power = False
        # Check k from 1 up to log2(m)
        for k in range(1, m.bit_length()):
            # Try to find p such that p^k = m
            p = round(m**(1/k))
            if p**k == m:
                # Check if p is prime
                is_p_prime = True
                if p < 2:
                    is_p_prime = False
                else:
                    for i in range(2, int(p**0.5) + 1):
                        if p % i == 0:
                            is_p_prime = False
                            break
                if is_p_prime:
                    is_prime_power = True
                    break
        if is_prime_power:
            count += 1
    return count

print(count_prime_powers(2000))

def count_prime_powers_correct(n):
    # Prime powers are p^k where p is prime and k >= 1
    prime_powers = set()
    for p in range(2, n + 1):
        # Check if p is prime
        is_p_prime = True
        if p < 2:
            is_p_prime = False
        else:
            for i in range(2, int(p**0.5) + 1):
                if p % i == 0:
                    is_p_prime = False
                    break
        if is_p_prime:
            # If p is prime, all p^k <= n are prime powers
            pk = p
            while pk <= n:
                prime_powers.add(pk)
                pk *= p
    return len(prime_powers)

