    for m in range(2, 11):
        all_multisets_work = True
        # For each multiset of size m from {0, ..., m-1}
        for multiset in itertools.combinations_with_replacement(range(m), m):
            s1 = sum(multiset) % m
            if s1 == 0:
                continue

            found_sigma = False
            # Condition 2: exists permutation sigma such that sum(j * x_{sigma(j)}) % m == 0
            # Let's use set(multiset) to avoid redundant permutations.
            # Wait, the permutation is over the multiset itself.
            # If the multiset has repeated elements, itertools.permutations will 
            # generate the same permutation multiple times. This is fine.
            for p in itertools.permutations(multiset):
                s2 = 0
                for j, val in enumerate(p):
                    s2 += (j + 1) * val
                if s2 % m == 0:
                    found_sigma = True
                    break

            if not found_sigma:
                print(f"m={m} fails for multiset {multiset}")
                all_multisets_work = False
                break

        if all_multisets_work:
            print(f"m={m} works")
        else:
            print(f"m={m} does not work")

