import itertools

def check_m_small_fixed(m):
    for multiset in itertools.combinations_with_replacement(range(m), m):
        s1 = sum(multiset) % m
        if s1 == 0:
            continue

        found_sigma = False
        n = len(multiset)
        dp = [[set() for _ in range(m)] for _ in range(n + 1)]
        dp[0][0].add(0)

        for i in range(n):
            for s in range(m):
                for mask in dp[i][s]:
                    for bit in range(n):
                        if not (mask & (1 << bit)):
                            new_mask = mask | (1 << bit)
                            new_sum = (s + (i + 1) * multiset[bit]) % m
                            dp[i+1][new_sum].add(new_mask)

        if dp[n][0]:
            found_sigma = True

        if not found_sigma:
            return False, multiset
    return True, None

