from itertools import combinations_with_replacement, permutations

def check_m(m):
    for residues in combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue

        found_perm = False
        # To optimize, notice that k_m can be any of the residues.
        # Let's try all possible residues to be k_m.
        for i in range(m):
            # residues[i] is k_m
            remaining = list(residues)
            remaining.pop(i)
            # Now we need to see if any permutation of 'remaining'
            # p_1, ..., p_{m-1} satisfies sum_{j=1}^{m-1} j * p_j = 0 mod m.
            for p in set(permutations(remaining)):
                s = 0
                for j in range(1, m):
                    s += j * p[j-1]
                if s % m == 0:
                    found_perm = True
                    break
            if found_perm:
                break

        if not found_perm:
            return False
    return True

