from itertools import combinations_with_replacement

def check_m_optimized(m):
    for residues in combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue

        possible_for_this_set = False
        for i in range(m):
            remaining = list(residues)
            remaining.pop(i)

            dp = [set() for _ in range(1 << (m-1))]
            dp[0].add(0)

            for mask in range(1 << (m-1)):
                if not dp[mask]: continue
                j = bin(mask).count('1') + 1
                if j > m-1: continue

                for k in range(m-1):
                    if not (mask & (1 << k)):
                        new_mask = mask | (1 << k)
                        for s in dp[mask]:
                            dp[new_mask].add((s + j * remaining[k]) % m)

            if 0 in dp[(1 << (m-1)) - 1]:
                possible_for_this_set = True
                break

        if not possible_for_this_set:
            return False
    return True

