def check_m_fast(m):
    for residues in combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue

        possible_for_this_set = False
        for i in range(m):
            remaining = list(residues)
            remaining.pop(i)

            dp = [0] * (1 << (m-1))
            dp[0] = 1

            for mask in range(1 << (m-1)):
                if dp[mask] == 0: continue
                j = bin(mask).count('1') + 1
                if j > m-1: continue

                for k in range(m-1):
                    if not (mask & (1 << k)):
                        v = (j * remaining[k]) % m
                        new_mask = mask | (1 << k)
                        dp[new_mask] |= ((dp[mask] << v) | (dp[mask] >> (m - v))) & ((1 << m) - 1)

            if dp[(1 << (m-1)) - 1] & 1:
                possible_for_this_set = True
                break

        if not possible_for_this_set:
            return False
    return True

